const SYMBOLS = ["QQQ", "EURUSD=X", "USO", "GLD", "HYG", "TLT", "BTC-USD"];
const RANGE = "5d"; // change to "2y" for a one-off historical backfill run, then change back to "5d"

return SYMBOLS.map(symbol => ({ json: { symbol, range: RANGE } }));

const allRows = [];
for (const item of $input.all()) {
  const chartResponse = item.json;
  const result = chartResponse?.chart?.result?.[0];
  if (!result) {
    const err = chartResponse?.chart?.error;
    console.log("Skipping item with no result: " + (err ? JSON.stringify(err) : "unknown shape"));
    continue;
  }
  const symbol = result.meta && result.meta.symbol;
  if (!symbol) {
    console.log("Skipping item with no meta.symbol — response shape may have changed.");
    continue;
  }
  const timestamps = result.timestamp || [];
  const closes = (result.indicators && result.indicators.quote && result.indicators.quote[0] && result.indicators.quote[0].close) || [];
  for (let i = 0; i < timestamps.length; i++) {
    const close = closes[i];
    if (close === null || close === undefined) continue; // non-trading session in range — skip, don't fabricate
    const date = new Date(timestamps[i] * 1000).toISOString().slice(0, 10);
    allRows.push({ date, symbol, close: Number(close) });
  }
}

if (allRows.length === 0) {
  throw new Error("Reshaped zero price rows — check the Fetch Yahoo Chart Data node's raw output; the endpoint may be blocked or the response shape may have changed.");
}

return allRows.map(r => ({ json: r }));
